/* ===== MINI-GAME: first-contact-hope (Steady the Flame) ===== */
const MG={active:false,armed:false,state:null,shown_tip:false};
function mgInit(){return{flame:0.5,decay:0.008,target:0.5,drift:0.0015,nomads:Array(8).fill(0).map((_,i)=>({angle:i*Math.PI/4,dist:12,commit:0,alive:true})),ticks:0,outcome:null};};
function mgStep(s,clicked){const ns={...s,nomads:s.nomads.map(n=>({...n})),ticks:s.ticks+1};if(ns.outcome)return ns;ns.flame=Math.max(0,Math.min(1,s.flame+(clicked?0.12:0)-s.decay));ns.target=0.5+Math.sin(s.ticks*s.drift)*0.15;const inBand=ns.flame>=ns.target-0.1&&ns.flame<=ns.target+0.15;const tooBright=ns.flame>ns.target+0.15;const tooDim=ns.flame<ns.target-0.1;for(const n of ns.nomads){if(!n.alive)continue;if(inBand){n.commit=Math.min(1,n.commit+0.03);n.dist=Math.max(2,n.dist-0.08);}else if(tooBright){n.commit=Math.max(0,n.commit-0.06);n.dist=Math.min(12,n.dist+0.15);if(n.commit<=0.2){n.alive=false;}}else if(tooDim){n.commit=Math.max(0,n.commit-0.04);n.dist=Math.min(12,n.dist+0.1);if(n.commit<=0.1){n.alive=false;}}}const alive=ns.nomads.filter(n=>n.alive);if(alive.length===0){ns.outcome=ns.flame>0.7?'flare':'dim';}else if(alive.every(n=>n.dist<=2.5&&n.commit>=0.9)){ns.outcome='win';}return ns;}
function mgResolve(s){if(s.outcome==='win')return['convert_devout',3];if(s.outcome==='flare')return['burnout',2];if(s.outcome==='dim')return['drift_apathy',1];return['no_effect',0];}
function mgOverlay(scene,s){const cx=SIM.player_pos[0]*CELL+CELL/2,cy=SIM.player_pos[1]*CELL+CELL/2;const flameH=s.flame*CELL*1.5;const flameCol=s.flame>s.target+0.15?0xffffff:s.flame<s.target-0.1?0xff4400:0xffdd44;scene.add.circle(cx,cy-CELL*0.5-flameH/2,flameH*0.4,flameCol,s.flame*0.8).setDepth(999);for(const n of s.nomads){if(!n.alive)continue;const nx=cx+Math.cos(n.angle)*n.dist*CELL,ny=cy+Math.sin(n.angle)*n.dist*CELL;const tint=n.commit>0.5?Phaser.Display.Color.Interpolate.ColorWithColor({r:128,g:128,b:128},{r:255,g:200,b:100},100,n.commit*100):0x808080;const lean=n.commit>0.6?0:(s.flame>s.target+0.15?-0.3:-0.2);scene.add.circle(nx,ny+lean*CELL,CELL*0.3,tint,0.9).setDepth(998);}}

