{const s0=mgInit();const s1=mgStep(s0,false);const decayed=s1.flame<s0.flame&&s1.flame>0;out.push(['M1 flame decays naturally',decayed,`${s0.flame.toFixed(3)}->${s1.flame.toFixed(3)}`]);}
// M2: mgStep click brightens flame
{const s0=mgInit();const s1=mgStep(s0,true);const bright=s1.flame>s0.flame;out.push(['M2 click brightens flame',bright,`${s0.flame.toFixed(3)}->${s1.flame.toFixed(3)}`]);}
// M3: mgResolve win yields convert_devout
{const s={outcome:'win'};const[eff,n]=mgResolve(s);out.push(['M3 win->convert_devout',eff==='convert_devout'&&n>0,`${eff},${n}`]);}
// M4: mgResolve flare yields burnout
{const s={outcome:'flare'};const[eff,n]=mgResolve(s);out.push(['M4 flare->burnout',eff==='burnout'&&n>0,`${eff},${n}`]);}
